param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$RomPath)
$ErrorActionPreference='Stop';$target="$PSScriptRoot/../evidence/mpu4/skill-cash"
if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Capture incomplete'}
if((Get-FileHash $RomPath -Algorithm SHA1).Hash -ne '402D1518BB78FDC489B06C2AABC771E5CE151847'){throw 'Unexpected ROM'}
$phase=@(Import-Csv "$RunDirectory/ptm-skill-cpu.csv"|Where-Object {$_.event -ne 'installed'});$original=@((Get-Content "$target/ptm-skill-cpu.json" -Raw|ConvertFrom-Json).rows)
if($phase.Count -ne $original.Count){throw 'Passive observation changed phase window'}
for($i=0;$i -lt $phase.Count;$i++){foreach($p in $original[$i].PSObject.Properties){if($phase[$i].($p.Name) -ne $p.Value){throw "Natural timer prefix differs at$i/$($p.Name)"}}}
$rows=@(Import-Csv "$RunDirectory/pia-service.csv");$entries=@($rows|Where-Object {$_.event -eq 'entry'});if($entries.Count -ne 19){throw 'Expected19 completed service entries'}
function Cycle($r){[ulong][decimal]::Round(([decimal]$r.seconds*1000000000000000000d+[decimal]$r.attoseconds)*1720000d/1000000000000000000d)}
$records=@(foreach($r in $rows){if($r.ram.Length -ne 2048){throw 'Missing RAM checkpoint'};[ordered]@{event=$r.event;address=[Convert]::ToInt32($r.address,16);data=[Convert]::ToInt32($r.data,16);cycle=(Cycle $r);c5ctl=[int]$r.c5ctl;c5ddr=[int]$r.c5ddr;c5out=[int]$r.c5out;c8ctl=[int]$r.c8ctl;c8ddr=[int]$r.c8ddr;c8out=[int]$r.c8out;ram_hex=$r.ram}})
[ordered]@{classification='Natural original Skill Cash campaign, passive PIA/RAM observer.354 original timer-state rows match field-for-field. Entry opcode fetch is instruction start+1; hardware accesses use observed bus time. No PIA read is performed merely for observation.';rows=$records}|ConvertTo-Json -Depth 5|Set-Content "$target/pia-service-timing.json"
[ordered]@{source_run=$RunDirectory;csv_sha256=(Get-FileHash "$RunDirectory/pia-service.csv").Hash;lua_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.lua").Hash;phase_sha256=(Get-FileHash "$RunDirectory/ptm-skill-cpu.csv").Hash;instructions_sha256=(Get-FileHash "$RunDirectory/ptm-instructions.csv").Hash;provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);phase_rows=$phase.Count;entries=$entries.Count;accesses=$rows.Count-$entries.Count}|ConvertTo-Json -Depth 6|Set-Content "$target/pia-service-timing-verification.json"
Write-Output "Curated $($entries.Count) natural service entries and $($rows.Count-$entries.Count) PIA accesses"
$rom=[IO.File]::ReadAllBytes($RomPath);$ranges=[ordered]@{}
foreach($r in @(@(0x40E9,63),@(0x43E4,1),@(0x4592,180),@(0x719C,1),@(0x71EE,4),@(0x7226,32),@(0xFF34,1),@(0xFF40,1),@(0xFF46,1),@(0xFF4C,1))){$ranges[$r[0].ToString('X4')]=[Convert]::ToHexString($rom[$r[0]..($r[0]+$r[1]-1)])}
$first=$entries[0];$ram=[Convert]::FromHexString($first.ram);$initial=$phase[0]
[ordered]@{classification='ROM-byte-checked static helper data and one natural Skill Cash entry hardware checkpoint; not timing events or a whole-machine startup model';rom_sha1=(Get-FileHash $RomPath -Algorithm SHA1).Hash;source='skill-cash/pia-service-timing.json';ranges=$ranges;panel_callback=($ram[0xC6]*256+$ram[0xC7]);drive_counter_before_first_service=(($ram[0x6E]-1) -band 255);c5_control=[int]$first.c5ctl;c5_direction=[int]$first.c5ddr;c5_output=[int]$first.c5out;c8_control=[int]$first.c8ctl;c8_direction=[int]$first.c8ddr;c8_output=[int]$first.c8out;timer3=[ordered]@{output_high=($initial.output3 -eq '1');single_fired=($initial.single3 -eq '1');latch=[int]$initial.latch3;counter=[int]$initial.counter3;pending=(([int]$initial.status -band 4) -ne 0);status_read=(([int]$initial.statusread -band 4) -ne 0)};qualification='Live AUX2 coin pins remain explicitly inactive. Full PIA interrupt/handshake effects and other reset/priority states are not modeled; native timing proof checks selected accesses. Static regions include code/inline data and unresolved branches, not a lossless ASM export.'}|ConvertTo-Json -Depth 5|Set-Content "$target/../maps/irq-service-data.json"
